#include "WristLinkView.h"
#include <cassert>
#include <cstdio>
int main(){lv_init();auto*d=lv_display_create(410,502);auto*parent=lv_obj_create(lv_screen_active());lv_obj_remove_style_all(parent);lv_obj_set_size(parent,410,454);lv_obj_set_pos(parent,0,48);wristlink::ControllerView view;unsigned throttle=0,calibrations=0;struct State{unsigned*t,*c;}state{&throttle,&calibrations};view.open(parent,[](void*p,unsigned v){*static_cast<State*>(p)->t=v;},[](void*p){++*static_cast<State*>(p)->c;},&state);view.update("Connected - controlling","Accel g: +0.00 +0.00 +1.00\nGyro deg/s: +0.0 +0.0 +0.0",500,true);lv_obj_update_layout(parent);auto*root=view.object();auto*slider=lv_obj_get_child(root,4);auto*cal=lv_obj_get_child(root,6);lv_area_t a;lv_obj_get_coords(cal,&a);assert(a.y2<478&&a.x1>=24&&a.x2<=386);lv_slider_set_value(slider,80,LV_ANIM_OFF);lv_obj_send_event(slider,LV_EVENT_VALUE_CHANGED,nullptr);assert(throttle==800);lv_obj_send_event(cal,LV_EVENT_CLICKED,nullptr);assert(calibrations==1);view.update("Calibrating. Keep still...","Accel g: +0.00 +0.00 +1.00\nGyro deg/s: +0.0 +0.0 +0.0",800,false);lv_obj_send_event(cal,LV_EVENT_CLICKED,nullptr);assert(calibrations==1);view.close();view.close();for(int i=0;i<30;++i){view.open(parent,nullptr,nullptr,nullptr);view.close();assert(lv_obj_get_child_count(parent)==0);}lv_display_delete(d);puts("WristLink view: rounded screen bounds, throttle, calibration gating, and 30 lifecycle cycles passed");}
